`timescale 1ns / 1ps

module controller_tb;

    // ====================================================
    // 1. 신호 선언
    // ====================================================
    reg clk, rstn, start;
    wire done;

    // Controller <-> BRAM Interface
    wire [15:0] bram_addr;
    wire [7:0]  bram_wdata;
    wire        bram_we;
    wire        bram_en;
    reg  [7:0]  bram_rdata;

    // Simulation Memory (64KB Fake BRAM)
    reg [7:0] fake_bram [0:65535];

    // [데이터 저장소] 100개 분량 확보
    reg [7:0] tb_weights [0:3219];      // 가중치
    reg [7:0] tb_images  [0:99][0:783]; // 이미지 (100장)
    integer   tb_labels  [0:99];        // 정답 라벨 (100개)

    // Loop Variables
    integer i, t, pass_cnt;
    integer max_val, max_idx, cur_val;
    reg [7:0] val_byte;

    // Address Map
    localparam ADDR_IMG     = 16'h0000;
    localparam ADDR_RESULT  = 16'h1000;
    localparam ADDR_WEIGHTS = 16'h2000;

    // ====================================================
    // 2. DUT Instantiation
    // ====================================================
    controller_1 dut (
        .clk(clk), .rstn(rstn), .start(start), .done(done),
        .bram_addr(bram_addr), .bram_wdata(bram_wdata), 
        .bram_we(bram_we), .bram_en(bram_en), .bram_rdata(bram_rdata)
    );

    // BRAM Logic
    always @(posedge clk) begin
        if (bram_en) begin
            if (bram_we) fake_bram[bram_addr] <= bram_wdata;
            bram_rdata <= fake_bram[bram_addr]; 
        end
    end

    // Clock
    initial begin clk = 0; forever #5 clk = ~clk; end

    // ====================================================
    // 3. Test Sequence
    // ====================================================
    initial begin
        // 초기화
        rstn = 0; start = 0; pass_cnt = 0;
        for(i=0; i<65536; i=i+1) fake_bram[i] = 0;
        
        // 배열 0으로 클리어
        for(i=0; i<3220; i=i+1) tb_weights[i] = 0;
        for(t=0; t<100; t=t+1) begin
            tb_labels[t] = 0;
            for(i=0; i<784; i=i+1) tb_images[t][i] = 0;
        end

        // -------------------------------------------------------------------------
        // [데이터 주입] - 아래 내용을 파이썬 생성 결과로 채워야 합니다.
        // (현재는 용량 관계상 '예시 데이터'만 넣습니다. 실제로는 전체를 넣어야 함)
