        // 1. 가중치 로드 (실제 값으로 교체 필요)
        // tb_weights[0] = ...; 
        
        // 2. 라벨 로드 (실제 값으로 교체 필요)
        // tb_labels[0] = 7;
        
        // 3. 이미지 로드 (실제 값으로 교체 필요)
