        // 1. 가중치 BRAM에 쓰기
        $display("Loading Weights to BRAM...");
        for(i=0; i<3220; i=i+1) fake_bram[ADDR_WEIGHTS + i] = tb_weights[i];

        // 리셋 해제
        #100 rstn = 1; #20;

        // 2. 100장 테스트 루프
        for (t = 0; t < 100; t = t + 1) begin
            
            // 이미지 BRAM에 쓰기
            for(i=0; i<784; i=i+1) fake_bram[ADDR_IMG + i] = tb_images[t][i];
            
            // Start
            wait(done == 0);
            $display("Test Image #%0d (Label: %0d) Start...", t, tb_labels[t]);
            @(posedge clk); start = 1;
            @(posedge clk); start = 0;

            // Wait Done
            @(posedge done);
            #200;

            // 결과 확인
            max_val = -9999; max_idx = 0;
            
            $write("  Scores: ");
            
            for(i=0; i<10; i=i+1) begin
                val_byte = fake_bram[ADDR_RESULT + i];
                cur_val = val_byte; // unsigned conversion
                $write("%d ", cur_val);

                if (cur_val > max_val) begin
                    max_val = cur_val;
                    max_idx = i;
                end
            end
            $display(""); 

            if (max_idx == tb_labels[t]) begin
                $display("  -> [PASS] Prediction: %0d", max_idx);
                pass_cnt = pass_cnt + 1;
            end else begin
                $display("  -> [FAIL] Prediction: %0d (Expected: %0d)", max_idx, tb_labels[t]);
            end
            $display("-------------------------------------------");
        end

        $display("Final Result: %0d / 100 PASSED", pass_cnt);
        $finish;
    end

endmodule